-- =====================================================
-- 初始数据 - 字典数据
-- 幂等依赖: sys_dict 唯一索引 sys_dict_uk_dict_code (sys_dict_code)
-- 不写主键：显式 id 与自增序列争抢时，INSERT IGNORE 只降级为告警，行会被静默丢弃
-- =====================================================


-- 子字典的父级 pid 需要按 code 反查 sys_dict 自身。MySQL 禁止 INSERT ... VALUES 的子查询
-- 引用目标表（ERROR 1093，会中断整个种子脚本），故改用 INSERT ... SELECT 自表取父行。
SELECT '短信', 'DUAN_XIN', p.`sys_dict_id`, 1, 0, '', NULL, '', 'sa', 1, NOW(), NOW(), 'sa', 1 FROM `sys_dict` p WHERE p.`sys_dict_code` = 'MU_BAN_LEI_XING';

SELECT '微信', 'WEI_XIN', p.`sys_dict_id`, 1, 0, NULL, NULL, NULL, 'sa', 1, NOW(), NULL, NULL, NULL FROM `sys_dict` p WHERE p.`sys_dict_code` = 'MU_BAN_LEI_XING';




